def normalize_weather(raw,date):
    if not isinstance(raw,dict): return None
    d=raw.get('daily')
    if not isinstance(d,dict) or not isinstance(d.get('time'),list) or date not in d['time']: return None
    try:
        i=d['time'].index(date)
        code=(d.get('weather_code') or d.get('weathercode'))[i]
        hi=d['temperature_2m_max'][i];lo=d['temperature_2m_min'][i]
        chance=(d.get('precipitation_probability_max') or [None]*len(d['time']))[i]
        import math
        if any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) for x in [code,hi,lo]):return None
        if code not in [0,1,2,3,45,48,51,53,55,56,57,61,63,65,66,67,71,73,75,77,80,81,82,85,86,95,96,97,99]:return None
        if code in [95,96,97,99]:category='storm'
        elif code in [71,73,75,77,85,86]:category='cold'
        elif code in [51,53,55,56,57,61,63,65,66,67,80,81,82] or isinstance(chance,(int,float)) and not isinstance(chance,bool) and chance>=60:category='rain'
        elif hi>=35:category='hot'
        elif lo<=10:category='cold'
        else:category='clear' if code in [0,1] else 'cloudy'
        return {'date':date,'category':category,'high':math.floor(hi+0.5),'low':math.floor(lo+0.5)}
    except (KeyError,IndexError,TypeError,ValueError):return None

def fetch_weather(p,date):
    if p.get('weather_enabled') is not True:return None
    lat=p.get('latitude');lon=p.get('longitude')
    import math
    if any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) for x in [lat,lon]) or abs(lat)>90 or abs(lon)>180:return None
    try:
        query=urllib.parse.urlencode({'latitude':lat,'longitude':lon,'daily':'weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max','timezone':'auto','forecast_days':'3','temperature_unit':'celsius'})
        with urllib.request.urlopen('https://api.open-meteo.com/v1/forecast?'+query,timeout=5) as response:raw=json.loads(response.read())
        return normalize_weather(raw,date)
    except Exception:return None

def weather_line(lang,w):
    if not w:return ''
    r=WEATHER[lang]
    return '🌦️ '+r['label']+' '+r['names'][w['category']]+' | '+(bn_digits(w['low']) if lang=='bn' else str(w['low']))+'-'+(bn_digits(w['high']) if lang=='bn' else str(w['high']))+'°C | Open-Meteo'

