WEATHER_MARKERS = {'clear': 'clear|sunny|আকাশ পরিষ্কার|রোদ|आसमान साफ|धूप', 'cloudy': 'cloud|fog|মেঘ|কুয়াশ|बादल|कोहर', 'rain': 'rain|umbrella|বৃষ্টি|ছাতা|बारिश|छाता', 'hot': 'heat|hot|গরম|गर्मी|गर्म', 'cold': 'cold|snow|warm layer|ঠান্ডা|তুষার|গরম জামা|ठंड|बर्फ|गर्म कप', 'storm': 'storm|thunder|ঝড়|বজ্র|तूफान|गरज'}

def clean_text(value,max_length=60):
    import re
    return re.sub(r'\s+',' ',re.sub(r'[\r\n\t<>]',' ',str(value or ''))).strip()[:max_length]

def context_for(p,date):
    lang=p['language'];month=int(date[5:7]);regional=p.get('panchang_india') is True and p.get('timezone') in ['Asia/Kolkata','Asia/Calcutta']
    import re
    local_bengal=regional and bool(re.search(r'krishnanagar|kolkata|siliguri|bardhaman|burdwan|malda|howrah|nadia|কৃষ্ণনগর|কলকাতা|শিলিগুড়ি|বর্ধমান|মালদা|হাওড়া|নদীয়া',p.get('location_label',''),re.I))
    season=('winter' if month==12 or month<=2 else 'spring' if month<=4 else 'summer' if month<=6 else 'monsoon' if month<=8 else 'autumn' if month<=10 else 'late_autumn') if local_bengal else None
    festival=('puja_before' if local_bengal and '2026-10-01'<=date<='2026-10-15' else 'puja' if local_bengal and '2026-10-16'<=date<='2026-10-21' else 'diwali' if date=='2026-11-08' else None) if regional else None
    return {'weekday':PIPELINE['week'][lang][(dt.date.fromisoformat(date).weekday()+1)%7],'season_context':PIPELINE['season'][lang][season] if season else '', 'festival_context':PIPELINE['festival'][lang][festival] if festival else ''}

def day_reading(p,date,weather=None):
    lang=p['language'];n=numbers(p['dob'],date)['values'];b=PIPELINE['bank'][lang];ctx=context_for(p,date)
    h=0
    for c in p['dob']+'|'+date+'|'+clean_text(p.get('display_name'))+'|'+clean_text(p.get('location_label')):h=(h*31+ord(c))%1000003
    variant=(h+n[0]*7+n[1]*11)%3;theme=n[4]-1
    return {'theme':n[4],'variant':variant,'morning_mood':b['morning'][theme][variant],'later_lift':b['lift'][theme][variant],'wisdom':b['wisdom'][theme],'gentle_caution':b['care'][theme],**ctx}

def digest_payload(p,date,weather=None):
    a=numbers(p['dob'],date)['values'];r=day_reading(p,date,weather)
    return {'kind':'digest','language':p['language'],'date':date,'name':clean_text(p.get('display_name')),'city':clean_text(p.get('location_label','').split(',')[0]),'weekday':r['weekday'],'season_context':r['season_context'],'festival_context':r['festival_context'],'weather':weather['category'] if weather else None,'weather_hint':WEATHER_NOTE_ADVICE[p['language']][weather['category']] if weather else '', 'numbers':dict(zip(['mulank','bhagyank','personal_year','personal_month','personal_day','universal_day'],a)), 'reading':{k:r[k] for k in ['theme','morning_mood','later_lift','gentle_caution','wisdom']}}

def greeting(p):
    name=clean_text(p.get('display_name'));suffix=', '+name if name else ''
    return {'bn':'🌅 শুভ সকাল'+suffix+'! ❤️','en':'🌅 Good morning'+suffix+'! ❤️','hi':'🌅 सुप्रभात'+suffix+'! ❤️'}[p['language']]

def temperature_tail(p,w):
    if not w:return ''
    low=bn_digits(w['low']) if p['language']=='bn' else str(w['low']);high=bn_digits(w['high']) if p['language']=='bn' else str(w['high'])
    return ' (🌦️ '+low+'-'+high+'°C, Open-Meteo)'

def normal_note(p,date,w=None):
    l=p['language'];r=day_reading(p,date,w);city=clean_text(p.get('location_label','').split(',')[0]) or {'bn':'তোমার শহর','en':'your city','hi':'तुम्हारे शहर'}[l]
    forecast={'bn':'আজ '+city+' শহরে '+WEATHER[l]['names'][w['category']]+'।','en':'In '+city+' today, '+WEATHER[l]['names'][w['category']]+'.','hi':'आज '+city+' में '+WEATHER[l]['names'][w['category']]+'।'}[l] if w else {'bn':'আজ '+r['weekday']+'।','en':'It is '+r['weekday']+' today.','hi':'आज '+r['weekday']+' है।'}[l]
    if l=='bn':
        arc=(r['weekday']+' সকালটা হয়তো '+r['morning_mood']+' নিয়ে শুরু হবে, কিন্তু বেলা বাড়লে '+r['later_lift']+'।' if r['variant']==0 else 'এই '+r['weekday']+' সকালে '+r['morning_mood']+' থাকতে পারে, তবে বেলা বাড়লে '+r['later_lift']+'।' if r['variant']==1 else 'এই '+r['weekday']+' সকালে '+r['morning_mood']+' থাকতে পারে, আর বেলা বাড়লে '+r['later_lift']+'।')
    elif l=='en':arc=(r['weekday']+' morning may bring '+r['morning_mood']+', but later '+r['later_lift']+'.' if r['variant']==0 else 'This '+r['weekday']+' could start with '+r['morning_mood']+'. As the day goes on, '+r['later_lift']+'.' if r['variant']==1 else 'You may start this '+r['weekday']+' with '+r['morning_mood']+'; later '+r['later_lift']+'.')
    else:arc=(r['weekday']+' सुबह '+r['morning_mood']+' हो सकती है, लेकिन दिन बढ़ने पर '+r['later_lift']+'।' if r['variant']==0 else 'इस '+r['weekday']+' की सुबह '+r['morning_mood']+' हो सकती है। दिन बढ़े तो '+r['later_lift']+'।' if r['variant']==1 else r['weekday']+' को शुरुआत में '+r['morning_mood']+' हो सकती है, फिर '+r['later_lift']+'।')
    note=' '.join(x for x in [forecast,r['festival_context'] or r['season_context'],arc,r['wisdom'],r['gentle_caution']] if x)
    return note+temperature_tail(p,w) if w else note+' '+WEATHER_NOTE_MISSING[l] if p.get('weather_enabled') is True else note

def weather_in_body(note,category):
    import re
    if not category:return True
    sentences=[s.strip() for s in re.split(r'[।.!?]+',note) if s.strip()]
    return len(sentences)>=2 and bool(re.search(WEATHER_MARKERS[category],' '.join(sentences[:-1]),re.I))

def digest_note(p,date,o,w):
    if w and not validate_digest(json.dumps(o,ensure_ascii=False),{'weather':w['category'],'language':p['language']}):return normal_note(p,date,w)
    return o['note']+(temperature_tail(p,w) if w else ' '+WEATHER_NOTE_MISSING[p['language']] if p.get('weather_enabled') is True else '')
def weather_media(lang,day,index,kind,category,fallback):
    if category=='rain' and index%2==0:
        m=RAIN_MEDIA[lang]
        return m['songs'][(index//2)%len(m['songs'])] if kind=='songs' else m['pod']
    if category and index%2==0:
        offsets={'clear':0,'cloudy':6,'hot':1,'cold':5,'storm':6}
        pool=SHORT_READING[lang][kind][offsets[category]]
        return pool[(day+index//2)%len(pool)]
    return fallback

